196:          fd_ = open64( fileName_, readFlags, 0 );
197: 
198:          readOnly_ = true;
199: 
200:          physicalLength_ = lseek64( 0LL, SEEK_END );
201:          lseek64( 0, SEEK_SET );
202: 
203:          logicalLength_ = physicalToLogical( physicalLength_ );
204:       }
205:       break;
206: 
207:       case Write:
208:       {
209:          // File truncated to zero length if already exists
210: 
211: #if defined( _MSC_VER )
212:          constexpr int writeFlags = O_RDWR | O_CREAT | O_TRUNC | O_BINARY;
213:          constexpr int writeMode = S_IREAD | S_IWRITE;
214: #else
215:          constexpr int writeFlags = O_RDWR | O_CREAT | O_TRUNC;
216:          constexpr int writeMode = S_IRUSR | S_IWUSR | S_IRGRP | S_IWGRP | S_IROTH | S_IWOTH;
217: #endif
218: 
219:          fd_ = open64( fileName_, writeFlags, writeMode );
220:       }
221:       break;
222:    }
223: }
