385: 
386:    uint64_t end = position( Logical ) + nWrite;
387: 
388:    uint64_t page = 0;
389:    size_t pageOffset = 0;
390: 
391:    getCurrentPageAndOffset( page, pageOffset );
392: 
393:    size_t n = std::min( nWrite, logicalPageSize - pageOffset );
394: 
395:    // Allocate temp page buffer
396:    std::vector<char> page_buffer_v( physicalPageSize );
397:    char *page_buffer = page_buffer_v.data();
398: 
399:    while ( nWrite > 0 )
400:    {
401:       const uint64_t physicalLength = length( Physical );
402: 
403:       if ( page * physicalPageSize < physicalLength )
404:       {
405:          readPhysicalPage( page_buffer, page );
406:       }
407: 
408: #ifdef E57_VERBOSE
409:       // cout << "  page_buffer[0] read: '" << page_buffer[0] << "'" << std::endl;
410:       // cout << "copy " << n << "bytes to page=" << page << " pageOffset=" <<
411:       // pageOffset << " buf='"; //??? for (size_t i=0; i < n; i++) cout <<
412:       // buf[i]; cout << "'" << std::endl;
413: #endif
414:       memcpy( page_buffer + pageOffset, buf, n );
415:       writePhysicalPage( page_buffer, page );
416: #ifdef E57_VERBOSE
417:       // cout << "  page_buffer[0] after write: '" << page_buffer[0] << "'" <<
418:       // std::endl; //???
419: #endif
420:       buf += n;
421:       nWrite -= n;
