710: void CheckedFile::verifyChecksum( char *page_buffer, uint64_t page )
711: {
712:    const uint32_t check_sum = checksum( page_buffer, logicalPageSize );
713:    const uint32_t check_sum_in_page =
714:       *reinterpret_cast<uint32_t *>( &page_buffer[logicalPageSize] );
715: 
716:    if ( check_sum_in_page != check_sum )
717:    {
718:       const uint64_t physicalLength = length( Physical );
719: 
720:       throw E57_EXCEPTION2( ErrorBadChecksum,
721:                             "fileName=" + fileName_ + " computedChecksum=" + toString( check_sum ) +
722:                                " storedChecksum=" + toString( check_sum_in_page ) + " page=" +
723:                                toString( page ) + " length=" + toString( physicalLength ) );
724:    }
725: }
