39:    @brief Reads the data out of a given image node
40: 
41:    @param [in] image 1 of 3 projects or the visual
42:    @param [in] imageType identifies the image format desired.
43:    @param [out] pBuffer pointer the buffer
44:    @param [out] start position in the block to start reading
45:    @param [out] count size of desired chunk or buffer size
46: 
47:    @return number of bytes read
48:    */
49:    size_t _readImage2DNode( const StructureNode &image, Image2DType imageType, uint8_t *pBuffer,
50:                             int64_t start, size_t count )
51:    {
52:       size_t transferred = 0;
53: 
54:       switch ( imageType )
55:       {
56:          case ImageNone:
57:             return 0;
58: 
59:          case ImageJPEG:
60:             if ( image.isDefined( "jpegImage" ) )
61:             {
62:                BlobNode jpegImage( image.get( "jpegImage" ) );
63:                jpegImage.read( pBuffer, start, count );
64:                transferred = count;
65:             }
66:             break;
67: 
68:          case ImagePNG:
69:             if ( image.isDefined( "pngImage" ) )
70:             {
71:                BlobNode pngImage( image.get( "pngImage" ) );
72:                pngImage.read( pBuffer, start, count );
73:                transferred = count;
74:             }
75:             break;
76: 
77:          case ImageMaskPNG:
78:             if ( image.isDefined( "imageMask" ) )
79:             {
80:                BlobNode imageMask( image.get( "imageMask" ) );
81:                imageMask.read( pBuffer, start, count );
82:                transferred = count;
83:             }
84:             break;
85:       }
86: 
87:       return transferred;
88:    }
89: 
90:    /*!
91:    @brief This function reads one of the image blobs
92: 
93:    @param [in] image 1 of 3 projects or the visual
94:    @param [out] imageType identifies the image format desired.
95:    @param [out] imageWidth The image width (in pixels).
96:    @param [out] imageHeight The image height (in pixels).
97:    @param [out] imageSize This is the total number of bytes for the image blob.
98:    @param [out] imageMaskType This is E57_PNG_IMAGE_MASK if "imageMask" is defined in the projection
99: 
100:    @return Returns true if successful
101:    */
102:    static bool _getImage2DNodeSizes( const StructureNode &image, Image2DType &imageType,
103:                                      int64_t &imageWidth, int64_t &imageHeight, int64_t &imageSize,
104:                                      Image2DType &imageMaskType )
105:    {
106:       imageWidth = 0;
107:       imageHeight = 0;
108:       imageSize = 0;
109:       imageType = ImageNone;
110:       imageMaskType = ImageNone;
111: 
112:       if ( image.isDefined( "imageWidth" ) )
113:       {
114:          imageWidth = IntegerNode( image.get( "imageWidth" ) ).value();
115:       }
116:       else
117:       {
118:          return false;
119:       }
120: 
121:       if ( image.isDefined( "imageHeight" ) )
122:       {
123:          imageHeight = IntegerNode( image.get( "imageHeight" ) ).value();
124:       }
125:       else
126:       {
127:          return false;
128:       }
129: 
130:       if ( image.isDefined( "jpegImage" ) )
131:       {
132:          imageSize = BlobNode( image.get( "jpegImage" ) ).byteCount();
133:          imageType = ImageJPEG;
134:       }
135:       else if ( image.isDefined( "pngImage" ) )
136:       {
137:          imageSize = BlobNode( image.get( "pngImage" ) ).byteCount();
138:          imageType = ImagePNG;
139:       }
140: 
141:       if ( image.isDefined( "imageMask" ) )
142:       {
143:          if ( imageType == ImageNone )
144:          {
145:             imageSize = BlobNode( image.get( "imageMask" ) ).byteCount();
146:             imageType = ImageMaskPNG;
147:          }
148: 
149:          imageMaskType = ImageMaskPNG;
150:       }
151: 
152:       return true;
153:    }
