155:    /// Possibly get min/max from the colour node itself instead of the colorLimits.
156:    void _readColourRanges( const std::string &protoName, const StructureNode &proto,
157:                            double &colourMin, double &colourMax )
158:    {
159:       // IF the colorLimits are not set
160:       // AND our colour node is
161:       // THEN get our min/max from the colour node itself.
162:       if ( ( colourMax == 0.0 ) && proto.isDefined( protoName ) )
163:       {
164:          const auto colourProto = proto.get( protoName );
165: 
166:          if ( colourProto.type() == TypeInteger )
167:          {
168:             const IntegerNode integerColour( colourProto );
169: 
170:             colourMin = static_cast<uint16_t>( integerColour.minimum() );
171:             colourMax = static_cast<uint16_t>( integerColour.maximum() );
172:          }
173:          else if ( colourProto.type() == TypeScaledInteger )
174:          {
175:             const ScaledIntegerNode scaledColour( colourProto );
176:             const double scale = scaledColour.scale();
177:             const double offset = scaledColour.offset();
178:             const int64_t minimum = scaledColour.minimum();
179:             const int64_t maximum = scaledColour.maximum();
180: 
181:             colourMin = static_cast<uint16_t>( minimum ) * scale + offset;
182:             colourMax = static_cast<uint16_t>( maximum ) * scale + offset;
183:          }
184:          else if ( colourProto.type() == TypeFloat )
185:          {
186:             const FloatNode floatColour( colourProto );
187: 
188:             colourMin = static_cast<uint16_t>( floatColour.minimum() );
189:             colourMax = static_cast<uint16_t>( floatColour.maximum() );
190:          }
191:       }
