240:       fileHeader.guid = StringNode( root_.get( "guid" ) ).value();
241:       if ( root_.isDefined( "e57LibraryVersion" ) )
242:       {
243:          fileHeader.e57LibraryVersion = StringNode( root_.get( "e57LibraryVersion" ) ).value();
244:       }
245: 
246:       if ( root_.isDefined( "coordinateMetadata" ) )
247:       {
248:          fileHeader.coordinateMetadata = StringNode( root_.get( "coordinateMetadata" ) ).value();
249:       }
250: 
251:       if ( root_.isDefined( "creationDateTime" ) )
252:       {
253:          const StructureNode creationDateTime( root_.get( "creationDateTime" ) );
254: 
255:          fileHeader.creationDateTime.dateTimeValue =
256:             FloatNode( creationDateTime.get( "dateTimeValue" ) ).value();
257: 
258:          if ( creationDateTime.isDefined( "isAtomicClockReferenced" ) )
