575:    // Returns the image sizes
576:    bool ReaderImpl::GetImage2DSizes( int64_t imageIndex, Image2DProjection &imageProjection,
577:                                      Image2DType &imageType, int64_t &imageWidth,
578:                                      int64_t &imageHeight, int64_t &imageSize,
579:                                      Image2DType &imageMaskType,
580:                                      Image2DType &imageVisualType ) const
581:    {
582:       if ( ( imageIndex < 0 ) || ( imageIndex >= images2D_.childCount() ) )
583:       {
584:          return false;
585:       }
586: 
587:       imageProjection = ProjectionNone;
588:       imageType = ImageNone;
589:       imageMaskType = ImageNone;
590:       imageVisualType = ImageNone;
591: 
592:       const StructureNode image( images2D_.get( imageIndex ) );
593: 
594:       if ( image.isDefined( "visualReferenceRepresentation" ) )
595:       {
596:          const StructureNode visualReferenceRepresentation(
597:             image.get( "visualReferenceRepresentation" ) );
598: 
599:          bool ret = _getImage2DNodeSizes( visualReferenceRepresentation, imageType, imageWidth,
600:                                           imageHeight, imageSize, imageMaskType );
601:          imageProjection = ProjectionVisual;
602:          imageVisualType = imageType;
603: 
604:          return ret;
605:       }
606: 
607:       if ( image.isDefined( "pinholeRepresentation" ) )
608:       {
609:          const StructureNode pinholeRepresentation( image.get( "pinholeRepresentation" ) );
610: 
611:          imageProjection = ProjectionPinhole;
612: 
613:          return _getImage2DNodeSizes( pinholeRepresentation, imageType, imageWidth, imageHeight,
614:                                       imageSize, imageMaskType );
615:       }
616: 
617:       if ( image.isDefined( "sphericalRepresentation" ) )
618:       {
619:          const StructureNode sphericalRepresentation( image.get( "sphericalRepresentation" ) );
620: 
621:          imageProjection = ProjectionSpherical;
622: 
623:          return _getImage2DNodeSizes( sphericalRepresentation, imageType, imageWidth, imageHeight,
624:                                       imageSize, imageMaskType );
625:       }
626: 
627:       if ( image.isDefined( "cylindricalRepresentation" ) )
628:       {
629:          const StructureNode cylindricalRepresentation( image.get( "cylindricalRepresentation" ) );
630: 
631:          imageProjection = ProjectionCylindrical;
632: 
633:          return _getImage2DNodeSizes( cylindricalRepresentation, imageType, imageWidth, imageHeight,
634:                                       imageSize, imageMaskType );
635:       }
636: 
637:       return false;
638:    }
