640:    // Reads the image data block
641:    size_t ReaderImpl::ReadImage2DData( int64_t imageIndex, Image2DProjection imageProjection,
642:                                        Image2DType imageType, uint8_t *pBuffer, int64_t start,
643:                                        size_t count ) const
644:    {
645:       if ( ( imageIndex < 0 ) || ( imageIndex >= images2D_.childCount() ) )
646:       {
647:          return 0;
648:       }
649: 
650:       const StructureNode image( images2D_.get( imageIndex ) );
651: 
652:       switch ( imageProjection )
653:       {
654:          case ProjectionNone:
655:             return 0;
656: 
657:          case ProjectionVisual:
658:             if ( image.isDefined( "visualReferenceRepresentation" ) )
659:             {
660:                const StructureNode visualReferenceRepresentation(
661:                   image.get( "visualReferenceRepresentation" ) );
662: 
663:                return _readImage2DNode( visualReferenceRepresentation, imageType, pBuffer, start,
664:                                         count );
665:             }
666:             break;
667: 
668:          case ProjectionPinhole:
669:             if ( image.isDefined( "pinholeRepresentation" ) )
670:             {
671:                const StructureNode pinholeRepresentation( image.get( "pinholeRepresentation" ) );
672: 
673:                return _readImage2DNode( pinholeRepresentation, imageType, pBuffer, start, count );
674:             }
675:             break;
676: 
677:          case ProjectionSpherical:
678:             if ( image.isDefined( "sphericalRepresentation" ) )
679:             {
680:                const StructureNode sphericalRepresentation(
681:                   image.get( "sphericalRepresentation" ) );
682: 
683:                return _readImage2DNode( sphericalRepresentation, imageType, pBuffer, start, count );
684:             }
685:             break;
686: 
687:          case ProjectionCylindrical:
688:             if ( image.isDefined( "cylindricalRepresentation" ) )
689:             {
690:                const StructureNode cylindricalRepresentation(
691:                   image.get( "cylindricalRepresentation" ) );
692: 
693:                return _readImage2DNode( cylindricalRepresentation, imageType, pBuffer, start,
694:                                         count );
695:             }
696:             break;
697:       }
698: 
699:       return 0;
700:    }
