702:    bool ReaderImpl::ReadData3D( int64_t dataIndex, Data3D &data3DHeader ) const
703:    {
704:       if ( !IsOpen() || ( dataIndex < 0 ) || ( dataIndex >= data3D_.childCount() ) )
705:       {
706:          return false;
707:       }
708: 
709:       data3DHeader = {};
710: 
711:       const StructureNode scan( data3D_.get( dataIndex ) );
712:       CompressedVectorNode points( scan.get( "points" ) );
713:       const StructureNode proto( points.prototype() );
714: 
715:       data3DHeader.guid = StringNode( scan.get( "guid" ) ).value();
716: 
717: #ifdef E57_32_BIT
718:       // If we exceed the size_t max, only process the max (4,294,967,295 points).
719:       if ( points.childCount() > static_cast<int64_t>( std::numeric_limits<size_t>::max() ) )
720:       {
721:          data3DHeader.pointCount = std::numeric_limits<size_t>::max();
722: 
723:          std::cout << "Warning (32-bit): Point count (" << points.childCount()
724:                    << ") exceeds storage capacity (" << std::numeric_limits<size_t>::max()
725:                    << "). Dropping " << points.childCount() - std::numeric_limits<size_t>::max()
726:                    << " points from scan." << std::endl;
727:       }
728:       else
729:       {
730:          data3DHeader.pointCount = static_cast<size_t>( points.childCount() );
731:       }
732: #else
733:       data3DHeader.pointCount = points.childCount();
734: #endif
735: 
736:       if ( scan.isDefined( "name" ) )
737:       {
738:          data3DHeader.name = StringNode( scan.get( "name" ) ).value();
739:       }
740:       if ( scan.isDefined( "description" ) )
741:       {
742:          data3DHeader.description = StringNode( scan.get( "description" ) ).value();
743:       }
744: 
745:       if ( scan.isDefined( "originalGuids" ) )
746:       {
747:          const VectorNode originalGuids( scan.get( "originalGuids" ) );
748: 
749:          if ( originalGuids.childCount() > 0 )
750:          {
751:             data3DHeader.originalGuids.clear();
752: 
753:             for ( int64_t i = 0; i < originalGuids.childCount(); ++i )
754:             {
755:                const ustring str = StringNode( originalGuids.get( i ) ).value();
756: 
757:                data3DHeader.originalGuids.push_back( str );
758:             }
759:          }
760:       }
761: 
762:       // Get various sensor and version strings from scan.
763:       if ( scan.isDefined( "sensorVendor" ) )
764:       {
765:          data3DHeader.sensorVendor = StringNode( scan.get( "sensorVendor" ) ).value();
766:       }
767:       if ( scan.isDefined( "sensorModel" ) )
768:       {
769:          data3DHeader.sensorModel = StringNode( scan.get( "sensorModel" ) ).value();
770:       }
771:       if ( scan.isDefined( "sensorSerialNumber" ) )
772:       {
773:          data3DHeader.sensorSerialNumber = StringNode( scan.get( "sensorSerialNumber" ) ).value();
774:       }
775:       if ( scan.isDefined( "sensorHardwareVersion" ) )
776:       {
777:          data3DHeader.sensorHardwareVersion =
778:             StringNode( scan.get( "sensorHardwareVersion" ) ).value();
779:       }
780:       if ( scan.isDefined( "sensorSoftwareVersion" ) )
781:       {
782:          data3DHeader.sensorSoftwareVersion =
783:             StringNode( scan.get( "sensorSoftwareVersion" ) ).value();
784:       }
785:       if ( scan.isDefined( "sensorFirmwareVersion" ) )
786:       {
787:          data3DHeader.sensorFirmwareVersion =
788:             StringNode( scan.get( "sensorFirmwareVersion" ) ).value();
789:       }
790: 
791:       // Get temp/humidity from scan.
792:       if ( scan.isDefined( "temperature" ) )
793:       {
794:          data3DHeader.temperature =
795:             static_cast<float>( FloatNode( scan.get( "temperature" ) ).value() );
796:       }
797:       if ( scan.isDefined( "relativeHumidity" ) )
798:       {
799:          data3DHeader.relativeHumidity =
800:             static_cast<float>( FloatNode( scan.get( "relativeHumidity" ) ).value() );
801:       }
802:       if ( scan.isDefined( "atmosphericPressure" ) )
803:       {
804:          data3DHeader.atmosphericPressure =
805:             static_cast<float>( FloatNode( scan.get( "atmosphericPressure" ) ).value() );
806:       }
807: 
808:       if ( scan.isDefined( "indexBounds" ) )
809:       {
810:          const StructureNode ibox( scan.get( "indexBounds" ) );
811: 
