200:    int64_t WriterImpl::NewImage2D( Image2D &image2DHeader )
201:    {
202:       StructureNode image( imf_ );
203: 
204:       images2D_.append( image );
205: 
206:       int64_t pos = images2D_.childCount() - 1;
207: 
208:       if ( image2DHeader.guid.empty() )
209:       {
210:          image2DHeader.guid = generateRandomGUID();
211:       }
212: 
213:       image.set( "guid", StringNode( imf_, image2DHeader.guid ) ); // required
214: 
215:       if ( !image2DHeader.name.empty() )
216:       {
217:          image.set( "name", StringNode( imf_, image2DHeader.name ) );
218:       }
219:       if ( !image2DHeader.description.empty() )
220:       {
221:          image.set( "description", StringNode( imf_, image2DHeader.description ) );
222:       }
223: 
224:       // Add various sensor and version strings to image.
225:       if ( !image2DHeader.sensorVendor.empty() )
226:       {
227:          image.set( "sensorVendor", StringNode( imf_, image2DHeader.sensorVendor ) );
228:       }
229:       if ( !image2DHeader.sensorModel.empty() )
230:       {
231:          image.set( "sensorModel", StringNode( imf_, image2DHeader.sensorModel ) );
232:       }
233:       if ( !image2DHeader.sensorSerialNumber.empty() )
234:       {
235:          image.set( "sensorSerialNumber", StringNode( imf_, image2DHeader.sensorSerialNumber ) );
236:       }
237: 
238:       if ( !image2DHeader.associatedData3DGuid.empty() )
239:       {
240:          image.set( "associatedData3DGuid",
241:                     StringNode( imf_, image2DHeader.associatedData3DGuid ) );
242:       }
243: 
244:       if ( image2DHeader.acquisitionDateTime.dateTimeValue > 0.0 )
245:       {
246:          StructureNode acquisitionDateTime( imf_ );
247: 
248:          image.set( "acquisitionDateTime", acquisitionDateTime );
249:          acquisitionDateTime.set(
250:             "dateTimeValue", FloatNode( imf_, image2DHeader.acquisitionDateTime.dateTimeValue ) );
251:          acquisitionDateTime.set(
252:             "isAtomicClockReferenced",
253:             IntegerNode( imf_, image2DHeader.acquisitionDateTime.isAtomicClockReferenced ) );
254:       }
255: 
256:       // Create pose structure for image.
257:       if ( image2DHeader.pose != RigidBodyTransform{} )
258:       {
259:          StructureNode pose( imf_ );
260:          image.set( "pose", pose );
261: 
262:          StructureNode rotation( imf_ );
263:          pose.set( "rotation", rotation );
264:          rotation.set( "w", FloatNode( imf_, image2DHeader.pose.rotation.w ) );
265:          rotation.set( "x", FloatNode( imf_, image2DHeader.pose.rotation.x ) );
266:          rotation.set( "y", FloatNode( imf_, image2DHeader.pose.rotation.y ) );
267:          rotation.set( "z", FloatNode( imf_, image2DHeader.pose.rotation.z ) );
268: 
269:          StructureNode translation( imf_ );
270:          pose.set( "translation", translation );
271:          translation.set( "x", FloatNode( imf_, image2DHeader.pose.translation.x ) );
272:          translation.set( "y", FloatNode( imf_, image2DHeader.pose.translation.y ) );
273:          translation.set( "z", FloatNode( imf_, image2DHeader.pose.translation.z ) );
274:       }
275: 
276:       if ( image2DHeader.visualReferenceRepresentation.jpegImageSize > 0 ||
277:            image2DHeader.visualReferenceRepresentation.pngImageSize > 0 )
278:       {
279:          StructureNode visualReferenceRepresentation( imf_ );
280:          image.set( "visualReferenceRepresentation", visualReferenceRepresentation );
281: 
282:          if ( image2DHeader.visualReferenceRepresentation.jpegImageSize > 0 )
283:          {
284:             visualReferenceRepresentation.set(
285:                "jpegImage",
286:                BlobNode( imf_, image2DHeader.visualReferenceRepresentation.jpegImageSize ) );
287:          }
288:          else if ( image2DHeader.visualReferenceRepresentation.pngImageSize > 0 )
289:          {
290:             visualReferenceRepresentation.set(
291:                "pngImage",
292:                BlobNode( imf_, image2DHeader.visualReferenceRepresentation.pngImageSize ) );
293:          }
294:          if ( image2DHeader.visualReferenceRepresentation.imageMaskSize > 0 )
295:          {
296:             visualReferenceRepresentation.set(
297:                "imageMask",
298:                BlobNode( imf_, image2DHeader.visualReferenceRepresentation.imageMaskSize ) );
299:          }
300: 
301:          visualReferenceRepresentation.set(
302:             "imageHeight",
303:             IntegerNode( imf_, image2DHeader.visualReferenceRepresentation.imageHeight ) );
304:          visualReferenceRepresentation.set(
305:             "imageWidth",
306:             IntegerNode( imf_, image2DHeader.visualReferenceRepresentation.imageWidth ) );
307:       }
308:       else if ( image2DHeader.pinholeRepresentation.jpegImageSize > 0 ||
309:                 image2DHeader.pinholeRepresentation.pngImageSize > 0 )
310:       {
311:          StructureNode pinholeRepresentation( imf_ );
312:          image.set( "pinholeRepresentation", pinholeRepresentation );
313: 
314:          if ( image2DHeader.pinholeRepresentation.jpegImageSize > 0 )
315:          {
316:             pinholeRepresentation.set(
317:                "jpegImage", BlobNode( imf_, image2DHeader.pinholeRepresentation.jpegImageSize ) );
318:          }
319:          else if ( image2DHeader.pinholeRepresentation.pngImageSize > 0 )
320:          {
321:             pinholeRepresentation.set(
322:                "pngImage", BlobNode( imf_, image2DHeader.pinholeRepresentation.pngImageSize ) );
323:          }
324:          if ( image2DHeader.pinholeRepresentation.imageMaskSize > 0 )
325:          {
326:             pinholeRepresentation.set(
327:                "imageMask", BlobNode( imf_, image2DHeader.pinholeRepresentation.imageMaskSize ) );
328:          }
329: 
330:          pinholeRepresentation.set(
331:             "focalLength", FloatNode( imf_, image2DHeader.pinholeRepresentation.focalLength ) );
332:          pinholeRepresentation.set(
333:             "imageHeight", IntegerNode( imf_, image2DHeader.pinholeRepresentation.imageHeight ) );
334:          pinholeRepresentation.set(
335:             "imageWidth", IntegerNode( imf_, image2DHeader.pinholeRepresentation.imageWidth ) );
336:          pinholeRepresentation.set(
337:             "pixelHeight", FloatNode( imf_, image2DHeader.pinholeRepresentation.pixelHeight ) );
338:          pinholeRepresentation.set(
339:             "pixelWidth", FloatNode( imf_, image2DHeader.pinholeRepresentation.pixelWidth ) );
340:          pinholeRepresentation.set(
341:             "principalPointX",
342:             FloatNode( imf_, image2DHeader.pinholeRepresentation.principalPointX ) );
343:          pinholeRepresentation.set(
344:             "principalPointY",
345:             FloatNode( imf_, image2DHeader.pinholeRepresentation.principalPointY ) );
346:       }
347:       else if ( image2DHeader.sphericalRepresentation.jpegImageSize > 0 ||
348:                 image2DHeader.sphericalRepresentation.pngImageSize > 0 )
349:       {
350:          StructureNode sphericalRepresentation( imf_ );
351:          image.set( "sphericalRepresentation", sphericalRepresentation );
352: 
353:          if ( image2DHeader.sphericalRepresentation.jpegImageSize > 0 )
354:          {
355:             sphericalRepresentation.set(
356:                "jpegImage", BlobNode( imf_, image2DHeader.sphericalRepresentation.jpegImageSize ) );
357:          }
358:          else if ( image2DHeader.sphericalRepresentation.pngImageSize > 0 )
359:          {
360:             sphericalRepresentation.set(
361:                "pngImage", BlobNode( imf_, image2DHeader.sphericalRepresentation.pngImageSize ) );
362:          }
363:          if ( image2DHeader.sphericalRepresentation.imageMaskSize > 0 )
364:          {
365:             sphericalRepresentation.set(
366:                "imageMask", BlobNode( imf_, image2DHeader.sphericalRepresentation.imageMaskSize ) );
367:          }
368: 
369:          sphericalRepresentation.set(
370:             "imageHeight", IntegerNode( imf_, image2DHeader.sphericalRepresentation.imageHeight ) );
371:          sphericalRepresentation.set(
372:             "imageWidth", IntegerNode( imf_, image2DHeader.sphericalRepresentation.imageWidth ) );
373:          sphericalRepresentation.set(
374:             "pixelHeight", FloatNode( imf_, image2DHeader.sphericalRepresentation.pixelHeight ) );
375:          sphericalRepresentation.set(
376:             "pixelWidth", FloatNode( imf_, image2DHeader.sphericalRepresentation.pixelWidth ) );
377:       }
378:       else if ( image2DHeader.cylindricalRepresentation.jpegImageSize > 0 ||
379:                 image2DHeader.cylindricalRepresentation.pngImageSize > 0 )
380:       {
381:          StructureNode cylindricalRepresentation( imf_ );
382:          image.set( "cylindricalRepresentation", cylindricalRepresentation );
383: 
384:          if ( image2DHeader.cylindricalRepresentation.jpegImageSize > 0 )
385:          {
386:             cylindricalRepresentation.set(
387:                "jpegImage",
388:                BlobNode( imf_, image2DHeader.cylindricalRepresentation.jpegImageSize ) );
389:          }
390:          else if ( image2DHeader.cylindricalRepresentation.pngImageSize > 0 )
391:          {
392:             cylindricalRepresentation.set(
393:                "pngImage", BlobNode( imf_, image2DHeader.cylindricalRepresentation.pngImageSize ) );
394:          }
395:          if ( image2DHeader.cylindricalRepresentation.imageMaskSize > 0 )
396:          {
397:             cylindricalRepresentation.set(
398:                "imageMask",
399:                BlobNode( imf_, image2DHeader.cylindricalRepresentation.imageMaskSize ) );
400:          }
401: 
402:          cylindricalRepresentation.set(
403:             "imageHeight",
404:             IntegerNode( imf_, image2DHeader.cylindricalRepresentation.imageHeight ) );
405:          cylindricalRepresentation.set(
406:             "imageWidth", IntegerNode( imf_, image2DHeader.cylindricalRepresentation.imageWidth ) );
407:          cylindricalRepresentation.set(
408:             "pixelHeight", FloatNode( imf_, image2DHeader.cylindricalRepresentation.pixelHeight ) );
409:          cylindricalRepresentation.set(
410:             "pixelWidth", FloatNode( imf_, image2DHeader.cylindricalRepresentation.pixelWidth ) );
411:          cylindricalRepresentation.set(
412:             "principalPointY",
413:             FloatNode( imf_, image2DHeader.cylindricalRepresentation.principalPointY ) );
414:          cylindricalRepresentation.set(
415:             "radius", FloatNode( imf_, image2DHeader.cylindricalRepresentation.radius ) );
416:       }
417: 
418:       // E57_LEICA_Camera_Distortion
419:       // See: http://www.libe57.org/E57_LEICA_Camera_Distortion.txt
420:       if ( image2DHeader.pinholeCameraDistortionExt )
421:       {
422:          // make sure we declare the extension before using the fields with prefix
423:          if ( !imf_.extensionsLookupPrefix( "dist" ) )
424:          {
425:             imf_.extensionsAdd( "dist", "http://www.libe57.org/E57_LEICA_Camera_Distortion.txt" );
426:          }
427: 
428:          StructureNode distortion( imf_ );
429:          image.set( "dist:distortion", distortion );
430: 
431:          const Extension::PinholeCameraDistortion *pcd =
432:             image2DHeader.pinholeCameraDistortionExt.get();
433:          if ( pcd->cameraNumber > 0 )
434:          {
435:             distortion.set( "dist:CameraNumber", IntegerNode( imf_, pcd->cameraNumber ) );
436:          }
437: 
438:          distortion.set( "dist:Type", StringNode( imf_, pcd->type ) );
439: 
440:          distortion.set( "dist:CV_K1", FloatNode( imf_, pcd->CV_K1 ) );
441:          distortion.set( "dist:CV_K2", FloatNode( imf_, pcd->CV_K2 ) );
442:          distortion.set( "dist:CV_K3", FloatNode( imf_, pcd->CV_K3 ) );
443:          distortion.set( "dist:CV_K4", FloatNode( imf_, pcd->CV_K4 ) );
444:          distortion.set( "dist:CV_K5", FloatNode( imf_, pcd->CV_K5 ) );
445:          distortion.set( "dist:CV_K6", FloatNode( imf_, pcd->CV_K6 ) );
446: 
447:          distortion.set( "dist:CV_P1", FloatNode( imf_, pcd->CV_P1 ) );
448:          distortion.set( "dist:CV_P2", FloatNode( imf_, pcd->CV_P2 ) );
449: 
450:          distortion.set( "dist:CV_CX", FloatNode( imf_, pcd->CV_CX ) );
451:          distortion.set( "dist:CV_CY", FloatNode( imf_, pcd->CV_CY ) );
452: 
453:          distortion.set( "dist:CV_FX", FloatNode( imf_, pcd->CV_FX ) );
454:          distortion.set( "dist:CV_FY", FloatNode( imf_, pcd->CV_FY ) );
455: 
456:          distortion.set( "dist:CV_HEIGHT",
457:                          IntegerNode( imf_, static_cast<int64_t>( pcd->CV_HEIGHT ) ) );
458: 
459:          distortion.set( "dist:CV_WIDTH",
460:                          IntegerNode( imf_, static_cast<int64_t>( pcd->CV_WIDTH ) ) );
461:       }
462: 
463:       return pos;
464:    }
