466:    size_t WriterImpl::WriteImage2DData( int64_t imageIndex, Image2DType imageType,
467:                                         Image2DProjection imageProjection, uint8_t *pBuffer,
468:                                         int64_t start, size_t count )
469:    {
470:       if ( ( imageIndex < 0 ) || ( imageIndex >= images2D_.childCount() ) )
471:       {
472:          return 0;
473:       }
474: 
475:       const StructureNode image( images2D_.get( imageIndex ) );
476: 
477:       switch ( imageProjection )
478:       {
479:          case ProjectionNone:
480:             return 0;
481: 
482:          case ProjectionVisual:
483:             if ( image.isDefined( "visualReferenceRepresentation" ) )
484:             {
485:                StructureNode visualReferenceRepresentation(
486:                   image.get( "visualReferenceRepresentation" ) );
487:                return _writeImage2DNode( visualReferenceRepresentation, imageType, pBuffer, start,
488:                                          count );
489:             }
490:             break;
491: 
492:          case ProjectionPinhole:
493:             if ( image.isDefined( "pinholeRepresentation" ) )
494:             {
495:                StructureNode pinholeRepresentation( image.get( "pinholeRepresentation" ) );
496:                return _writeImage2DNode( pinholeRepresentation, imageType, pBuffer, start, count );
497:             }
498:             break;
499: 
500:          case ProjectionSpherical:
501:             if ( image.isDefined( "sphericalRepresentation" ) )
502:             {
503:                StructureNode sphericalRepresentation( image.get( "sphericalRepresentation" ) );
504:                return _writeImage2DNode( sphericalRepresentation, imageType, pBuffer, start,
505:                                          count );
506:             }
507:             break;
508: 
509:          case ProjectionCylindrical:
510:             if ( image.isDefined( "cylindricalRepresentation" ) )
511:             {
512:                StructureNode cylindricalRepresentation( image.get( "cylindricalRepresentation" ) );
513:                return _writeImage2DNode( cylindricalRepresentation, imageType, pBuffer, start,
514:                                          count );
515:             }
516:             break;
517:       }
518: 
519:       return 0;
520:    }
