522:    int64_t WriterImpl::NewData3D( Data3D &data3DHeader )
523:    {
524:       StructureNode scan( imf_ );
525:       data3D_.append( scan );
526: 
527:       int64_t pos = data3D_.childCount() - 1;
528: 
529:       if ( data3DHeader.guid.empty() )
530:       {
531:          data3DHeader.guid = generateRandomGUID();
532:       }
533: 
534:       scan.set( "guid", StringNode( imf_, data3DHeader.guid ) );
535: 
536:       if ( !data3DHeader.name.empty() )
537:       {
538:          scan.set( "name", StringNode( imf_, data3DHeader.name ) );
539:       }
540: 
541:       if ( !data3DHeader.description.empty() )
542:       {
543:          scan.set( "description", StringNode( imf_, data3DHeader.description ) );
544:       }
545: 
546:       if ( !data3DHeader.originalGuids.empty() )
547:       {
548:          scan.set( "originalGuids", VectorNode( imf_ ) );
549: 
550:          VectorNode originalGuids( scan.get( "originalGuids" ) );
551: 
552:          for ( const auto &guid : data3DHeader.originalGuids )
553:          {
554:             originalGuids.append( StringNode( imf_, guid ) );
555:          }
556:       }
557: 
558:       // Add various sensor and version strings to scan.
559:       // Path names: "/data3D/0/sensorVendor", etc...
560:       if ( !data3DHeader.sensorVendor.empty() )
561:       {
562:          scan.set( "sensorVendor", StringNode( imf_, data3DHeader.sensorVendor ) );
563:       }
564: 
565:       if ( !data3DHeader.sensorModel.empty() )
566:       {
567:          scan.set( "sensorModel", StringNode( imf_, data3DHeader.sensorModel ) );
568:       }
569: 
570:       if ( !data3DHeader.sensorSerialNumber.empty() )
571:       {
572:          scan.set( "sensorSerialNumber", StringNode( imf_, data3DHeader.sensorSerialNumber ) );
573:       }
574: 
575:       if ( !data3DHeader.sensorHardwareVersion.empty() )
576:       {
577:          scan.set( "sensorHardwareVersion",
578:                    StringNode( imf_, data3DHeader.sensorHardwareVersion ) );
579:       }
580: 
581:       if ( !data3DHeader.sensorSoftwareVersion.empty() )
582:       {
583:          scan.set( "sensorSoftwareVersion",
584:                    StringNode( imf_, data3DHeader.sensorSoftwareVersion ) );
585:       }
586: 
587:       if ( !data3DHeader.sensorFirmwareVersion.empty() )
588:       {
589:          scan.set( "sensorFirmwareVersion",
590:                    StringNode( imf_, data3DHeader.sensorFirmwareVersion ) );
591:       }
592: 
593:       // Add temp/humidity to scan.
594:       // Path names: "/data3D/0/temperature", etc...
595:       if ( data3DHeader.temperature != FLOAT_MAX )
596:       {
597:          scan.set( "temperature", FloatNode( imf_, data3DHeader.temperature ) );
598:       }
599: 
600:       if ( data3DHeader.relativeHumidity != FLOAT_MAX )
601:       {
602:          scan.set( "relativeHumidity", FloatNode( imf_, data3DHeader.relativeHumidity ) );
603:       }
604: 
605:       if ( data3DHeader.atmosphericPressure != FLOAT_MAX )
606:       {
607:          scan.set( "atmosphericPressure", FloatNode( imf_, data3DHeader.atmosphericPressure ) );
608:       }
609: 
610:       if ( data3DHeader.indexBounds != IndexBounds{} )
611:       {
612:          StructureNode ibox( imf_ );
613: 
614:          if ( ( data3DHeader.indexBounds.rowMinimum != 0 ) ||
615:               ( data3DHeader.indexBounds.rowMaximum != 0 ) )
616:          {
617:             ibox.set( "rowMinimum", IntegerNode( imf_, data3DHeader.indexBounds.rowMinimum ) );
618:             ibox.set( "rowMaximum", IntegerNode( imf_, data3DHeader.indexBounds.rowMaximum ) );
619:          }
620: 
621:          if ( ( data3DHeader.indexBounds.columnMinimum != 0 ) ||
622:               ( data3DHeader.indexBounds.columnMaximum != 0 ) )
623:          {
624:             ibox.set( "columnMinimum",
625:                       IntegerNode( imf_, data3DHeader.indexBounds.columnMinimum ) );
626:             ibox.set( "columnMaximum",
627:                       IntegerNode( imf_, data3DHeader.indexBounds.columnMaximum ) );
628:          }
629: 
630:          if ( ( data3DHeader.indexBounds.returnMinimum != 0 ) ||
631:               ( data3DHeader.indexBounds.returnMaximum != 0 ) )
632:          {
633:             ibox.set( "returnMinimum",
634:                       IntegerNode( imf_, data3DHeader.indexBounds.returnMinimum ) );
635:             ibox.set( "returnMaximum",
636:                       IntegerNode( imf_, data3DHeader.indexBounds.returnMaximum ) );
637:          }
638: 
639:          scan.set( "indexBounds", ibox );
640:       }
641: 
642:       if ( ( data3DHeader.intensityLimits.intensityMaximum != 0.0 ) ||
643:            ( data3DHeader.intensityLimits.intensityMinimum != 0.0 ) )
644:       {
645:          StructureNode intbox( imf_ );
646: 
647:          const double intensityMin = data3DHeader.intensityLimits.intensityMinimum;
648:          const double intensityMax = data3DHeader.intensityLimits.intensityMaximum;
649: 
650:          switch ( data3DHeader.pointFields.intensityNodeType )
651:          {
652:             case NumericalNodeType::Integer:
653:             {
654:                intbox.set( "intensityMinimum",
655:                            IntegerNode( imf_, static_cast<int64_t>( intensityMin ) ) );
656:                intbox.set( "intensityMaximum",
657:                            IntegerNode( imf_, static_cast<int64_t>( intensityMax ) ) );
658: 
659:                break;
660:             }
661: 
662:             case NumericalNodeType::ScaledInteger:
663:             {
664:                const double scale = data3DHeader.pointFields.intensityScale;
665:                const double offset = 0.0;
666: 
667:                const auto rawIntegerMinimum =
668:                   static_cast<int64_t>( std::floor( ( intensityMin - offset ) / scale + .5 ) );
669:                const auto rawIntegerMaximum =
670:                   static_cast<int64_t>( std::floor( ( intensityMax - offset ) / scale + .5 ) );
671: 
672:                intbox.set( "intensityMinimum",
673:                            ScaledIntegerNode( imf_, rawIntegerMinimum, rawIntegerMinimum,
674:                                               rawIntegerMaximum, scale, offset ) );
675:                intbox.set( "intensityMaximum",
676:                            ScaledIntegerNode( imf_, rawIntegerMaximum, rawIntegerMinimum,
677:                                               rawIntegerMaximum, scale, offset ) );
678: 
679:                break;
680:             }
681: 
682:             case NumericalNodeType::Float:
683:             {
684:                intbox.set( "intensityMinimum", FloatNode( imf_, intensityMin, PrecisionSingle ) );
685:                intbox.set( "intensityMaximum", FloatNode( imf_, intensityMax, PrecisionSingle ) );
686: 
687:                break;
688:             }
689: 
690:             case NumericalNodeType::Double:
691:             {
692:                intbox.set( "intensityMinimum", FloatNode( imf_, intensityMin, PrecisionDouble ) );
693:                intbox.set( "intensityMaximum", FloatNode( imf_, intensityMax, PrecisionDouble ) );
694: 
695:                break;
696:             }
697:          }
698: 
699:          scan.set( "intensityLimits", intbox );
700:       }
701: 
702:       if ( ( data3DHeader.colorLimits.colorRedMaximum != 0.0 ) ||
