746:       if ( ( data3DHeader.sphericalBounds.rangeMinimum != 0.0 ) ||
747:            ( data3DHeader.sphericalBounds.rangeMaximum != DOUBLE_MAX ) )
748:       {
749:          StructureNode sbox( imf_ );
