763:       // Create pose structure for scan.
764:       // Path names: "/data3D/0/pose/rotation/w", etc...
765:       //             "/data3D/0/pose/translation/x", etc...
766:       if ( data3DHeader.pose != RigidBodyTransform{} )
767:       {
