800:       }
801:       if ( data3DHeader.acquisitionEnd.dateTimeValue > 0.0 )
802:       {
803:          StructureNode acquisitionEnd( imf_ );
804: 
805:          acquisitionEnd.set( "dateTimeValue",
806:                              FloatNode( imf_, data3DHeader.acquisitionEnd.dateTimeValue ) );
807:          acquisitionEnd.set(
808:             "isAtomicClockReferenced",
809:             IntegerNode( imf_, data3DHeader.acquisitionEnd.isAtomicClockReferenced ) );
810: 
811:          scan.set( "acquisitionEnd", acquisitionEnd );
812:       }
813: 
814:       // Add grouping scheme area
815:       // Path name: "/data3D/0/pointGroupingSchemes"
816:       if ( !data3DHeader.pointGroupingSchemes.groupingByLine.idElementName.empty() )
817:       {
818:          StructureNode pointGroupingSchemes( imf_ );
819: 
820:          // Add a line grouping scheme
821:          // Path name: "/data3D/0/pointGroupingSchemes/groupingByLine"
822:          StructureNode groupingByLine( imf_ );
823: 
824:          // data3DHeader.pointGroupingSchemes.groupingByLine.idElementName));
825:          bool byColumn = true; // default should be "columnIndex"
826:          if ( data3DHeader.pointGroupingSchemes.groupingByLine.idElementName == "rowIndex" )
827:          {
828:             byColumn = false;
829:          }
830: 
831:          // Add idElementName to groupingByLine, specify a line is column or row oriented
832:          // Path name: "/data3D/0/pointGroupingSchemes/groupingByLine/idElementName"
833:          if ( byColumn )
834:          {
835:             groupingByLine.set( "idElementName", StringNode( imf_, "columnIndex" ) );
836:          }
837:          else
838:          {
839:             groupingByLine.set( "idElementName", StringNode( imf_, "rowIndex" ) );
840:          }
841: 
842:          // Make a prototype of datatypes that will be stored in LineGroupRecord.
843:          // This prototype will be used in creating the groups CompressedVector.
844:          // Will define path names like:
845:          //     "/data3D/0/pointGroupingSchemes/groupingByLine/groups/0/idElementValue"
846:          const int64_t groupsSize = data3DHeader.pointGroupingSchemes.groupingByLine.groupsSize;
847:          const int64_t countSize = data3DHeader.pointGroupingSchemes.groupingByLine.pointCountSize;
848:          const int64_t pointsCount = data3DHeader.pointCount;
849: 
850:          StructureNode lineGroupProto( imf_ );
851: 
852:          lineGroupProto.set( "startPointIndex", IntegerNode( imf_, 0, 0, pointsCount - 1 ) );
853:          lineGroupProto.set( "idElementValue", IntegerNode( imf_, 0, 0, groupsSize - 1 ) );
854:          lineGroupProto.set( "pointCount", IntegerNode( imf_, 0, 0, countSize ) );
855: 
856:          // Make empty codecs vector for use in creating groups CompressedVector.
857:          // If this vector is empty, it is assumed that all fields will use the BitPack codec.
858:          const VectorNode lineGroupCodecs( imf_, true );
859: 
860:          // Create CompressedVector for storing groups.
861:          // Path Name: "/data3D/0/pointGroupingSchemes/groupingByLine/groups".
862:          // We use the prototype and empty codecs tree from above.
863:          // The CompressedVector will be filled by code below.
864:          const CompressedVectorNode groups( imf_, lineGroupProto, lineGroupCodecs );
865: 
866:          groupingByLine.set( "groups", groups );
867:          pointGroupingSchemes.set( "groupingByLine", groupingByLine );
868:          scan.set( "pointGroupingSchemes", pointGroupingSchemes );
869:       }
870: 
871:       // Make a prototype of datatypes that will be stored in points record.
872:       // This prototype will be used in creating the points CompressedVector.
873:       // Using this proto in a CompressedVector will define path names like:
874:       //      "/data3D/0/points/0/cartesianX"
875:       StructureNode proto( imf_ );
876: 
877:       const double pointRangeMin = data3DHeader.pointFields.pointRangeMinimum;
878:       const double pointRangeMax = data3DHeader.pointFields.pointRangeMaximum;
879: 
880:       const auto getPointProto = [=]() -> Node {
881:          switch ( data3DHeader.pointFields.pointRangeNodeType )
882:          {
883:             case NumericalNodeType::Integer:
884:             {
885:                throw E57_EXCEPTION2( ErrorInvalidNodeType, "pointRangeNodeType cannot be Integer" );
886:             }
887: 
888:             case NumericalNodeType::ScaledInteger:
889:             {
890:                // Because ScaledInteger min/max are the raw integer min/max, we must calculate them
891:                // from the data min/max
892:                const double pointRangeOffset = 0.0;
893:                const double pointRangeScale = data3DHeader.pointFields.pointRangeScale;
894: 
895:                if ( pointRangeScale == 0.0 )
896:                {
897:                   throw E57_EXCEPTION2( ErrorInvalidData3DValue, "pointRangeScale cannot be 0" );
898:                }
899: 
900:                const auto pointRangeMinimum = static_cast<int64_t>(
901:                   std::floor( ( pointRangeMin - pointRangeOffset ) / pointRangeScale + .5 ) );
902:                const auto pointRangeMaximum = static_cast<int64_t>(
903:                   std::floor( ( pointRangeMax - pointRangeOffset ) / pointRangeScale + .5 ) );
904: 
905:                return ScaledIntegerNode( imf_, 0, pointRangeMinimum, pointRangeMaximum,
906:                                          pointRangeScale, pointRangeOffset );
907:             }
908: 
909:             case NumericalNodeType::Float:
910:             {
911:                return FloatNode( imf_, 0.0, PrecisionSingle, pointRangeMin, pointRangeMax );
912:             }
913: 
914:             case NumericalNodeType::Double:
915:             {
916:                return FloatNode( imf_, 0.0, PrecisionDouble, pointRangeMin, pointRangeMax );
917:             }
918:          }
919: 
920:          throw E57_EXCEPTION2(
921:             ErrorInvalidNodeType,
922:             std::string( "Invalid pointRangeNodeType type: " )
923:                .append( _numericalNodeTypeStr( data3DHeader.pointFields.pointRangeNodeType ) ) );
924:       };
925: 
926:       if ( data3DHeader.pointFields.cartesianXField )
927:       {
928:          proto.set( "cartesianX", getPointProto() );
929:       }
930: 
931:       if ( data3DHeader.pointFields.cartesianYField )
932:       {
933:          proto.set( "cartesianY", getPointProto() );
934:       }
935: 
936:       if ( data3DHeader.pointFields.cartesianZField )
937:       {
938:          proto.set( "cartesianZ", getPointProto() );
939:       }
940: 
941:       if ( data3DHeader.pointFields.sphericalRangeField )
942:       {
943:          proto.set( "sphericalRange", getPointProto() );
944:       }
945: 
946:       const double angleMin = data3DHeader.pointFields.angleMinimum;
947:       const double angleMax = data3DHeader.pointFields.angleMaximum;
948: 
949:       const auto getAngleProto = [=]() -> Node {
950:          switch ( data3DHeader.pointFields.angleNodeType )
951:          {
952:             case NumericalNodeType::Integer:
953:             {
954:                throw E57_EXCEPTION2( ErrorInvalidNodeType, "angleNodeType cannot be Integer" );
955:             }
956: 
957:             case NumericalNodeType::ScaledInteger:
958:             {
959:                const double angleOffset = 0.0;
960:                const double angleScale = data3DHeader.pointFields.angleScale;
961: 
962:                if ( angleScale == 0.0 )
963:                {
964:                   throw E57_EXCEPTION2( ErrorInvalidData3DValue, "angleScale cannot be 0" );
965:                }
966: 
967:                const auto angleMinimum = static_cast<int64_t>(
968:                   std::floor( ( angleMin - angleOffset ) / angleScale + .5 ) );
969:                const auto angleMaximum = static_cast<int64_t>(
970:                   std::floor( ( angleMax - angleOffset ) / angleScale + .5 ) );
971: 
972:                return ScaledIntegerNode( imf_, 0, angleMinimum, angleMaximum, angleScale,
973:                                          angleOffset );
974:             }
975: 
976:             case NumericalNodeType::Float:
977:             {
978:                return FloatNode( imf_, 0.0, PrecisionSingle, angleMin, angleMax );
979:             }
980: 
981:             case NumericalNodeType::Double:
982:             {
983:                return FloatNode( imf_, 0.0, PrecisionDouble, angleMin, angleMax );
984:             }
985:          }
986: 
987:          throw E57_EXCEPTION2(
988:             ErrorInvalidNodeType,
989:             std::string( "Invalid angleNodeType type: " )
990:                .append( _numericalNodeTypeStr( data3DHeader.pointFields.angleNodeType ) ) );
991:       };
992: 
993:       if ( data3DHeader.pointFields.sphericalAzimuthField )
994:       {
995:          proto.set( "sphericalAzimuth", getAngleProto() );
996:       }
997: 
998:       if ( data3DHeader.pointFields.sphericalElevationField )
999:       {
1000:          proto.set( "sphericalElevation", getAngleProto() );
1001:       }
1002: 
1003:       if ( data3DHeader.pointFields.intensityField )
1004:       {
1005:          const double intensityMin = data3DHeader.intensityLimits.intensityMinimum;
1006:          const double intensityMax = data3DHeader.intensityLimits.intensityMaximum;
1007: 
1008:          switch ( data3DHeader.pointFields.intensityNodeType )
1009:          {
1010:             case NumericalNodeType::Integer:
1011:             {
1012:                proto.set( "intensity", IntegerNode( imf_, 0, static_cast<int64_t>( intensityMin ),
1013:                                                     static_cast<int64_t>( intensityMax ) ) );
1014: 
1015:                break;
1016:             }
1017: 
1018:             case NumericalNodeType::ScaledInteger:
1019:             {
1020:                const double scale = data3DHeader.pointFields.intensityScale;
1021:                const double offset = 0.0; // could be data3DHeader.intensityLimits.intensityMinimum;
1022: 
1023:                const auto rawIntegerMaximum =
1024:                   static_cast<int64_t>( std::floor( ( intensityMax - offset ) / scale + .5 ) );
1025:                const auto rawIntegerMinimum =
1026:                   static_cast<int64_t>( std::floor( ( intensityMin - offset ) / scale + .5 ) );
1027: 
1028:                proto.set( "intensity", ScaledIntegerNode( imf_, 0, rawIntegerMinimum,
1029:                                                           rawIntegerMaximum, scale, offset ) );
1030: 
1031:                break;
1032:             }
1033: 
1034:             case NumericalNodeType::Float:
1035:             {
1036:                proto.set( "intensity", FloatNode( imf_, 0.0, PrecisionSingle,
1037:                                                   data3DHeader.intensityLimits.intensityMinimum,
1038:                                                   data3DHeader.intensityLimits.intensityMaximum ) );
1039: 
1040:                break;
1041:             }
1042: 
1043:             case NumericalNodeType::Double:
1044:             {
1045:                proto.set( "intensity", FloatNode( imf_, 0.0, PrecisionDouble,
1046:                                                   data3DHeader.intensityLimits.intensityMinimum,
1047:                                                   data3DHeader.intensityLimits.intensityMaximum ) );
1048: 
1049:                break;
1050:             }
1051:          }
1052:       }
1053: 
1054:       if ( data3DHeader.pointFields.colorRedField )
1055:       {
1056:          proto.set(
1057:             "colorRed",
1058:             IntegerNode( imf_, 0, static_cast<int64_t>( data3DHeader.colorLimits.colorRedMinimum ),
1059:                          static_cast<int64_t>( data3DHeader.colorLimits.colorRedMaximum ) ) );
1060:       }
1061:       if ( data3DHeader.pointFields.colorGreenField )
1062:       {
1063:          proto.set( "colorGreen",
1064:                     IntegerNode(
1065:                        imf_, 0, static_cast<int64_t>( data3DHeader.colorLimits.colorGreenMinimum ),
1066:                        static_cast<int64_t>( data3DHeader.colorLimits.colorGreenMaximum ) ) );
1067:       }
1068:       if ( data3DHeader.pointFields.colorBlueField )
1069:       {
1070:          proto.set(
1071:             "colorBlue",
1072:             IntegerNode( imf_, 0, static_cast<int64_t>( data3DHeader.colorLimits.colorBlueMinimum ),
1073:                          static_cast<int64_t>( data3DHeader.colorLimits.colorBlueMaximum ) ) );
1074:       }
1075: 
1076:       if ( data3DHeader.pointFields.returnIndexField )
1077:       {
1078:          proto.set( "returnIndex",
1079:                     IntegerNode( imf_, 0, UINT8_MIN, data3DHeader.pointFields.returnMaximum ) );
1080:       }
1081:       if ( data3DHeader.pointFields.returnCountField )
1082:       {
1083:          proto.set( "returnCount",
1084:                     IntegerNode( imf_, 0, UINT8_MIN, data3DHeader.pointFields.returnMaximum ) );
1085:       }
1086: 
1087:       if ( data3DHeader.pointFields.rowIndexField )
1088:       {
1089:          proto.set( "rowIndex",
1090:                     IntegerNode( imf_, 0, UINT32_MIN, data3DHeader.pointFields.rowIndexMaximum ) );
1091:       }
1092:       if ( data3DHeader.pointFields.columnIndexField )
1093:       {
1094:          proto.set( "columnIndex", IntegerNode( imf_, 0, UINT32_MIN,
1095:                                                 data3DHeader.pointFields.columnIndexMaximum ) );
1096:       }
1097: 
1098:       if ( data3DHeader.pointFields.timeStampField )
1099:       {
1100:          const double timeMinimum = data3DHeader.pointFields.timeMinimum;
1101:          const double timeMaximum = data3DHeader.pointFields.timeMaximum;
1102: 
1103:          switch ( data3DHeader.pointFields.timeNodeType )
1104:          {
1105:             case NumericalNodeType::Integer:
1106:             {
1107:                proto.set( "timeStamp", IntegerNode( imf_, 0, static_cast<int64_t>( timeMinimum ),
1108:                                                     static_cast<int64_t>( timeMaximum ) ) );
1109:                break;
1110:             }
1111: 
1112:             case NumericalNodeType::ScaledInteger:
1113:             {
1114:                const double scale = data3DHeader.pointFields.timeScale;
1115:                const double offset = 0.0;
1116: 
1117:                const auto rawIntegerMinimum =
1118:                   static_cast<int64_t>( std::floor( ( timeMinimum - offset ) / scale + .5 ) );
1119:                const auto rawIntegerMaximum =
1120:                   static_cast<int64_t>( std::floor( ( timeMaximum - offset ) / scale + .5 ) );
1121: 
1122:                proto.set( "timeStamp", ScaledIntegerNode( imf_, 0, rawIntegerMinimum,
1123:                                                           rawIntegerMaximum, scale, offset ) );
1124:                break;
1125:             }
1126: 
1127:             case NumericalNodeType::Float:
1128:             {
1129:                proto.set( "timeStamp",
1130:                           FloatNode( imf_, 0.0, PrecisionSingle, FLOAT_MIN, FLOAT_MAX ) );
1131:                break;
1132:             }
1133: 
1134:             case NumericalNodeType::Double:
1135:             {
1136:                proto.set( "timeStamp",
1137:                           FloatNode( imf_, 0.0, PrecisionDouble, DOUBLE_MIN, DOUBLE_MAX ) );
1138:                break;
1139:             }
1140:          }
1141:       }
1142: 
1143:       if ( data3DHeader.pointFields.cartesianInvalidStateField )
1144:       {
1145:          proto.set( "cartesianInvalidState", IntegerNode( imf_, 0, 0, 2 ) );
1146:       }
1147:       if ( data3DHeader.pointFields.sphericalInvalidStateField )
1148:       {
1149:          proto.set( "sphericalInvalidState", IntegerNode( imf_, 0, 0, 2 ) );
1150:       }
1151:       if ( data3DHeader.pointFields.isIntensityInvalidField )
1152:       {
1153:          proto.set( "isIntensityInvalid", IntegerNode( imf_, 0, 0, 1 ) );
1154:       }
1155:       if ( data3DHeader.pointFields.isColorInvalidField )
1156:       {
1157:          proto.set( "isColorInvalid", IntegerNode( imf_, 0, 0, 1 ) );
1158:       }
1159:       if ( data3DHeader.pointFields.isTimeStampInvalidField )
1160:       {
1161:          proto.set( "isTimeStampInvalid", IntegerNode( imf_, 0, 0, 1 ) );
1162:       }
1163: 
1164:       // E57_EXT_surface_normals
1165:       // See: http://www.libe57.org/E57_EXT_surface_normals.txt
1166:       if ( data3DHeader.pointFields.normalXField || data3DHeader.pointFields.normalYField ||
1167:            data3DHeader.pointFields.normalZField )
1168:       {
1169:          // make sure we declare the extension before using the fields with prefix
1170:          if ( !imf_.extensionsLookupPrefix( "nor" ) )
1171:          {
1172:             imf_.extensionsAdd( "nor", "http://www.libe57.org/E57_EXT_surface_normals.txt" );
1173:          }
1174:       }
1175: 
1176:       // currently we support writing normals only as float32
1177:       if ( data3DHeader.pointFields.normalXField )
1178:       {
1179:          proto.set( "nor:normalX", FloatNode( imf_, 0.0, PrecisionSingle, -1.0, 1.0 ) );
1180:       }
1181:       if ( data3DHeader.pointFields.normalYField )
1182:       {
1183:          proto.set( "nor:normalY", FloatNode( imf_, 0.0, PrecisionSingle, -1.0, 1.0 ) );
1184:       }
1185:       if ( data3DHeader.pointFields.normalZField )
1186:       {
1187:          proto.set( "nor:normalZ", FloatNode( imf_, 0.0, PrecisionSingle, -1.0, 1.0 ) );
1188:       }
1189: 
1190:       // Make empty codecs vector for use in creating points CompressedVector.
1191:       // If this vector is empty, it is assumed that all fields will use the BitPack codec.
1192:       const VectorNode codecs( imf_, true );
1193: 
1194:       // Create CompressedVector for storing points.  Path Name: "/data3D/0/points".
1195:       // We use the prototype and empty codecs tree from above.
1196:       // The CompressedVector will be filled by code below.
1197:       const CompressedVectorNode points( imf_, proto, codecs );
1198: 
1199:       scan.set( "points", points );
1200: 
1201:       return pos;
1202:    }
