1204:    template <typename COORDTYPE>
1205:    CompressedVectorWriter WriterImpl::SetUpData3DPointsData(
1206:       int64_t dataIndex, size_t count, const Data3DPointsData_t<COORDTYPE> &buffers )
1207:    {
1208:       static_assert( std::is_floating_point<COORDTYPE>::value, "Floating point type required." );
1209: 
1210:       const StructureNode scan( data3D_.get( dataIndex ) );
1211:       CompressedVectorNode points( scan.get( "points" ) );
1212:       const StructureNode proto( points.prototype() );
1213:       std::vector<SourceDestBuffer> sourceBuffers;
1214: 
1215:       if ( proto.isDefined( "cartesianX" ) && ( buffers.cartesianX != nullptr ) )
1216:       {
1217:          sourceBuffers.emplace_back( imf_, "cartesianX", buffers.cartesianX, count, true, true );
1218:       }
1219: 
1220:       if ( proto.isDefined( "cartesianY" ) && ( buffers.cartesianY != nullptr ) )
1221:       {
1222:          sourceBuffers.emplace_back( imf_, "cartesianY", buffers.cartesianY, count, true, true );
1223:       }
1224: 
1225:       if ( proto.isDefined( "cartesianZ" ) && ( buffers.cartesianZ != nullptr ) )
1226:       {
1227:          sourceBuffers.emplace_back( imf_, "cartesianZ", buffers.cartesianZ, count, true, true );
1228:       }
1229: 
1230:       if ( proto.isDefined( "sphericalRange" ) && ( buffers.sphericalRange != nullptr ) )
1231:       {
1232:          sourceBuffers.emplace_back( imf_, "sphericalRange", buffers.sphericalRange, count, true,
1233:                                      true );
1234:       }
